import openpyxl
wb = openpyxl.load_workbook('3_177-6_answer_inconsistent_color_4079_input.xlsx')
ws = wb['combined']
for r in range(1, ws.max_row+1):
    for c in range(1, ws.max_column+1):
        cell = ws.cell(row=r, column=c)
        f = cell.fill
        desc = 'none'
        if f and f.patternType:
            col = f.fgColor
            if col.type == 'rgb':
                desc = f'RGB:{col.rgb}'
            elif col.type == 'theme':
                desc = f'T{col.theme}:{col.tint}'
            else:
                desc = f'{col.type}:{col.rgb}'
        print(f'{cell.coordinate}={cell.value!r} fill={desc}')
    print('---')
